# Let me figure out what the actual transformations should be by examining each case carefully
inputs = ['chfb', 'xbzi', 'ghej', 'hxkyag', 'ejjwb']
outputs = ['chff', 'xfbi', 'jkhej', 'hxkyajk', 'ejjwf']

# Analyze what needs to happen for each input
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input {i}: '{inp}' → Output {i}: '{out}'")

    # Find characters that differ
    diff_positions = []
    for j, (char_in, char_out) in enumerate(zip(inp, out)):
        if char_in != char_out:
            diff_positions.append((j, char_in, char_out))

    if len(out) > len(inp):
        # Added characters
        added_chars = out[len(inp):]
        print(f"  Added characters: '{added_chars}'")
    elif len(out) < len(inp):
        # Removed characters
        removed_chars = inp[len(out):]
        print(f"  Removed characters: '{removed_chars}'")

    if diff_positions:
        for pos, char_in, char_out in diff_positions:
            print(f"  Position {pos}: '{char_in}' → '{char_out}'")
    else:
        print("  No character changes (same length)")
    print()

