outputs = ['chff', 'xfbi', 'jkhej', 'hxkyajk', 'ejjwf']

# Let me look at the actual characters that differ
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Input:  '{inp}' ({len(inp)} chars)")
    print(f"Output: '{out}' ({len(out)} chars)")
    if len(inp) != len(out):
        print(f"MISMATCH IN LENGTH!")
    else:
        diffs = [(j, inp[j], out[j]) for j in range(len(inp)) if inp[j] != out[j]]
        if diffs:
            print("Differences:")
            for pos, in_char, out_char in diffs:
                print(f"  Position {pos}: '{in_char}' → '{out_char}'")
        else:
            print("No character differences")
    print()

